func (s *Session) Append(msgs ...schema.Message) {
    s.mu.Lock()
    defer s.mu.Unlock()
    s.history = append(s.history, msgs...)
    s.UpdatedAt = time.Now()

    // 【持久化预留点】：在真实的工业级实现中（如 Claude Code），
    // 我们会在这里将 s.history 以 JSONL 的格式 Append 到 workDir/.claw/sessions/xxx.jsonl 中。
