type SessionManager struct {
    sessions map[string]*Session
    mu       sync.RWMutex
}

func (sm *SessionManager) GetOrCreate(id string, workDir string) *Session {
    sm.mu.Lock()
    defer sm.mu.Unlock()

    if sess, exists := sm.sessions[id]; exists {
        return sess
    }
    sess := NewSession(id, workDir)
    sm.sessions[id] = sess
    return sess
}

